from pymatgen.core import Structure
from pymatgen.analysis.defects.core import PeriodicSite, Substitution, Vacancy, Interstitial, DefectComplex
from pymatgen.core.periodic_table import Specie

def calculate_material_properties():
    """
    Calculates various properties of a defect complex in a material using Pymatgen.

    Returns:
        dict: A dictionary containing calculated material properties such as defect complex name, supercell formulas,
              oxidation state checks, element changes, and defect complex equality/inequality status.
    """
    results = {}

    try:
        # Load the GaN structure from the specified file
        file_path = 'tool_source_code/pymatgen-analysis-defects/tests/test_files/GaN.vasp'
        gan_struct = Structure.from_file(file_path)
    except Exception as e:
        return {"error": f"Failed to load structure: {str(e)}"}

    try:
        # Create defect complexes
        s = gan_struct.copy()
        o_site = PeriodicSite(Specie("O"), s[3].frac_coords, s.lattice)
        sub = Substitution(s, o_site)  # O substituted on N site
        vac = Vacancy(s, s.sites[0])  # Ga vacancy
        inter = Interstitial(s, PeriodicSite(Specie("H"), [0, 0, 0.75], s.lattice))  # H interstitial
        dc = DefectComplex([sub, vac])
        dc2 = DefectComplex([sub, vac, inter])

        # Calculate each property and handle errors

        # 1. Defect complex name
        try:
            results['defect_complex_name'] = str(dc)
        except Exception:
            results['defect_complex_name'] = None

        # 2. Supercell structure formula
        try:
            results['supercell_structure_formula'] = dc.structure.composition.formula
        except Exception:
            results['supercell_structure_formula'] = None

        # 3. Defect complex oxidation state
        try:
            results['defect_complex_oxidation_state'] = (dc.oxi_state == sum(defect.oxi_state for defect in dc.defects))
        except Exception:
            results['defect_complex_oxidation_state'] = None

        # 4. Element changes
        try:
            results['element_changes'] = dc.element_changes
        except Exception:
            results['element_changes'] = None

        # 5. Defect structure formula
        try:
            results['defect_structure_formula'] = dc.defect_structure.composition.formula
        except Exception:
            results['defect_structure_formula'] = None

        # 6. Defect complex with interstitial name
        try:
            results['defect_complex_with_interstitial_name'] = str(dc2)
        except Exception:
            results['defect_complex_with_interstitial_name'] = None

        # 7. Supercell structure with dummy formula
        try:
            dc2.structure.append("Xe", [0, 0, 0.75])  # Add dummy species Xe
            results['supercell_structure_with_dummy_formula'] = dc2.structure.composition.formula
        except Exception:
            results['supercell_structure_with_dummy_formula'] = None

        # 8. Defect complex equality
        try:
            results['defect_complex_equality'] = (dc2 == dc2)
        except Exception:
            results['defect_complex_equality'] = None

        # 9. Defect complex inequality
        try:
            results['defect_complex_inequality'] = (dc != dc2)
        except Exception:
            results['defect_complex_inequality'] = None

    except Exception as e:
        return {"error": f"Failed to calculate properties: {str(e)}"}

    return results

from collections import defaultdict
from pathlib import Path
from pymatgen.core import Structure, PeriodicSite
from pymatgen.core.periodic_table import Element
from pymatgen.io.vasp import Vasprun, Locpot
from pymatgen.analysis.defects.entries import DefectEntry
from pymatgen.analysis.defects.generators import Substitution
from pymatgen.analysis.defects.thermo import FormationEnergyDiagram
from pymatgen.analysis.phase_diagram import PhaseDiagram
from monty.serialization import loadfn
from pymatgen.analysis.defects.plotting.thermo import plot_formation_energy_diagrams

def calculate_material_properties():
    """
    Calculate material properties using Pymatgen, specifically the defect names from
    the formation energy diagram.

    Returns:
        dict: A dictionary containing the calculated properties.
    """
    try:
        test_files_dir = Path.cwd() / 'tool_source_code/pymatgen-analysis-defects/tests/test_files/'

        # Load data
        def test_dir():
            return test_files_dir

        def data_Mg_Ga(test_dir):
            root_dir = test_dir / "Mg_Ga"
            data = defaultdict(dict)
            for fold in root_dir.glob("./*"):
                if not fold.is_dir():
                    continue
                data[fold.name] = {
                    "vasprun": Vasprun(fold / "vasprun.xml.gz"),
                    "locpot": Locpot.from_file(fold / "LOCPOT.gz"),
                }
            return data

        def gan_struct(test_dir):
            return Structure.from_file(test_dir / "GaN.vasp")

        def defect_Mg_Ga(gan_struct):
            ga_site = gan_struct[0]
            mg_site = PeriodicSite(Element("Mg"), ga_site.frac_coords, gan_struct.lattice)
            return Substitution(gan_struct, mg_site)

        def defect_entries_and_plot_data_Mg_Ga(data_Mg_Ga, defect_Mg_Ga):
            bulk_locpot = data_Mg_Ga["bulk_sc"]["locpot"]

            def get_data(q):
                computed_entry = data_Mg_Ga[f"q={q}"]["vasprun"].get_computed_entry(
                    inc_structure=True
                )
                defect_locpot = data_Mg_Ga[f"q={q}"]["locpot"]

                def_entry = DefectEntry(
                    defect=defect_Mg_Ga, charge_state=q, sc_entry=computed_entry
                )
                frey_summary = def_entry.get_freysoldt_correction(
                    defect_locpot=defect_locpot, bulk_locpot=bulk_locpot, dielectric=14
                )
                return def_entry, frey_summary

            defect_entries = dict()
            plot_data = dict()
            for qq in [-2, -1, 0, 1]:
                defect_entry, frey_summary = get_data(qq)
                defect_entries[qq] = defect_entry
                plot_data[qq] = frey_summary.metadata["plot_data"]
            return defect_entries, plot_data

        def stable_entries_Mg_Ga_N(test_dir):
            return loadfn(test_dir / "stable_entries_Mg_Ga_N.json")

        def basic_fed(data_Mg_Ga, defect_entries_and_plot_data_Mg_Ga, stable_entries_Mg_Ga_N):
            bulk_vasprun = data_Mg_Ga["bulk_sc"]["vasprun"]
            bulk_bs = bulk_vasprun.get_band_structure()
            vbm = bulk_bs.get_vbm()["energy"]
            bulk_entry = bulk_vasprun.get_computed_entry(inc_structure=False)
            defect_entries, _ = defect_entries_and_plot_data_Mg_Ga
            def_ent_list = list(defect_entries.values())
            atomic_entries = list(
                filter(lambda x: len(x.composition.elements) == 1, stable_entries_Mg_Ga_N)
            )
            pd = PhaseDiagram(stable_entries_Mg_Ga_N)
            fed = FormationEnergyDiagram.with_atomic_entries(
                defect_entries=def_ent_list,
                atomic_entries=atomic_entries,
                vbm=vbm,
                inc_inf_values=False,
                phase_diagram=pd,
                bulk_entry=bulk_entry,
            )
            fed.band_gap = 2
            return fed

        # Calculate formation energy diagram defect names
        try:
            fed = basic_fed(
                data_Mg_Ga(test_dir()),
                defect_entries_and_plot_data_Mg_Ga(data_Mg_Ga(test_dir()), defect_Mg_Ga(gan_struct(test_dir()))),
                stable_entries_Mg_Ga_N(test_dir())
            )
            fig = plot_formation_energy_diagrams([fed])
            formation_energy_diagram_defect_names = {d_.name for d_ in fig.data}
        except Exception:
            formation_energy_diagram_defect_names = None

        return {
            "formation_energy_diagram_defect_names": formation_energy_diagram_defect_names
        }

    except Exception as e:
        return {
            "formation_energy_diagram_defect_names": None
        }

from pymatgen.core import Structure
from pymatgen.analysis.defects.core import Interstitial, PeriodicSite
from pymatgen.core.periodic_table import Specie
from pymatgen.analysis.defects.finder import DefectSiteFinder
from pathlib import Path

def calculate_interstitial_defect_properties():
    """Calculate various properties for an interstitial defect in a GaN structure.

    Returns:
        dict: A dictionary with property names as keys and calculated results as values.
    """
    results = {}

    try:
        # Load structure from file
        file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files")
        gan_struct = Structure.from_file(file_path / "GaN.vasp")

        # Add oxidation states to the structure
        try:
            gan_struct.add_oxidation_state_by_guess()
        except Exception:
            pass  # Handle failure to assign oxidation states gracefully

        # Generate interstitial defect
        s = gan_struct.copy()
        inter_fpos = [0, 0, 0.75]
        n_site = PeriodicSite(Specie("N"), inter_fpos, s.lattice)
        inter = Interstitial(s, n_site)
        finder = DefectSiteFinder()
        inter2 = Interstitial(s, n_site)

        # Calculate properties
        try:
            results['oxidation_state'] = inter.site.specie.oxi_state
        except Exception:
            results['oxidation_state'] = None

        try:
            results['charge_states'] = inter.charge_states
        except Exception:
            results['charge_states'] = None

        results['fractional_coordinates'] = list(inter.site.frac_coords)

        try:
            results['supercell_formula'] = inter.structure.composition.formula
        except Exception:
            results['supercell_formula'] = None

        results['defect_name'] = inter.name

        results['defect_string_representation'] = str(inter)

        try:
            results['element_changes'] = inter.element_changes
        except Exception:
            results['element_changes'] = None

        try:
            results['latex_name'] = inter.latex_name
        except Exception:
            results['latex_name'] = None

        try:
            results['defect_fpos_initial'] = list(finder.get_defect_fpos(inter)[0])
        except Exception:
            results['defect_fpos_initial'] = None

        try:
            # Modify the defect site to the target fractional coordinates
            inter2.site = PeriodicSite(inter.site.specie, [0.3, 0.5, 0.9], s.lattice)
            results['defect_fpos_modified'] = list(inter2.site.frac_coords)
        except Exception:
            results['defect_fpos_modified'] = None

        # User-defined charge states
        try:
            inter2.user_charge_states = [-100, 102]
            results['user_defined_charge_states'] = inter2.user_charge_states
        except Exception:
            results['user_defined_charge_states'] = None

    except Exception as e:
        print(f"An error occurred: {e}")
        # Set all properties to None on total failure
        results = {key: None for key in results}

    return results

from pymatgen.core import Structure, Element
from pymatgen.analysis.defects.core import PeriodicSite, Substitution
from pymatgen.analysis.defects.finder import DefectSiteFinder

def calculate_material_properties():
    """
    Calculate various material properties using Pymatgen.

    Returns:
        dict: A dictionary containing calculated material properties.
    """
    # Define the file path to the GaN.vasp structure
    file_path = "tool_source_code/pymatgen-analysis-defects/tests/test_files/GaN.vasp"

    # Load the GaN structure
    gan_struct = Structure.from_file(file_path)

    # Initialize results dictionary
    results = {}

    try:
        # Create a substitution defect
        s = gan_struct.copy()
        n_site = s.sites[3]
        o_site = PeriodicSite(Element("O"), n_site.frac_coords, s.lattice)
        sub = Substitution(s, o_site)

        # Calculate properties
        results['site_specie_symbol'] = o_site.specie.symbol
    except Exception:
        results['site_specie_symbol'] = None

    try:
        results['substitution_symmetry_equivalence'] = sub.equivalent_sites is not None
    except Exception:
        results['substitution_symmetry_equivalence'] = None

    try:
        results['substitution_string_representation'] = str(sub)
    except Exception:
        results['substitution_string_representation'] = None

    try:
        results['substitution_oxidation_state'] = sub.oxi_state
    except Exception:
        results['substitution_oxidation_state'] = None

    try:
        results['substitution_charge_states'] = sub.get_charge_states()
    except Exception:
        results['substitution_charge_states'] = None

    try:
        results['substitution_multiplicity'] = sub.multiplicity
    except Exception:
        results['substitution_multiplicity'] = None

    try:
        sc, site_ = sub.get_supercell_structure(return_site=True)
        results['supercell_site_specie_symbol'] = site_.specie.symbol
        results['supercell_formula'] = sc.formula
    except Exception:
        results['supercell_site_specie_symbol'] = None
        results['supercell_formula'] = None

    try:
        results['substitution_name'] = sub.name
    except Exception:
        results['substitution_name'] = None

    try:
        results['substitution_latex_name'] = sub.latex_name
    except Exception:
        results['substitution_latex_name'] = None

    try:
        results['substitution_element_changes'] = sub.element_changes
    except Exception:
        results['substitution_element_changes'] = None

    try:
        sc_locked = sub.get_supercell_structure(relax_radius=5.0)
        free_sites = [i for i, site in enumerate(sc_locked) if site.properties.get("selective_dynamics", [False])[0]]
        free_sites_ref = [site.index for site in sc_locked.get_sites_in_sphere(site_.coords, 5.0, include_index=True)]
        results['free_sites_intersection_ratio'] = len(set(free_sites).intersection(set(free_sites_ref))) / len(set(free_sites).union(set(free_sites_ref)))
    except Exception:
        results['free_sites_intersection_ratio'] = None

    try:
        sc_locked_perturbed = sub.get_supercell_structure(relax_radius=5.0, perturb=0.0)
        free_sites_perturbed = [site.index for site in sc_locked_perturbed.get_sites_in_sphere(site_.coords, 5.0, include_index=True)]
        results['perturbation_free_sites'] = set(free_sites) == set(free_sites_perturbed)
    except Exception:
        results['perturbation_free_sites'] = None

    try:
        results['user_defined_charge_states'] = sub.user_charges
    except Exception:
        results['user_defined_charge_states'] = None

    try:
        results['default_charge_states'] = sub.get_charge_states() if not sub.user_charges else []
    except Exception:
        results['default_charge_states'] = None

    try:
        finder = DefectSiteFinder()
        fpos = finder.get_defect_fpos(sc, sub.structure)
        results['target_fractional_coordinates'] = fpos
    except Exception:
        results['target_fractional_coordinates'] = None

    try:
        fpos = finder.get_defect_fpos(sc_locked, sub.structure)
        results['closest_equivalent_site_coordinates'] = fpos
    except Exception:
        results['closest_equivalent_site_coordinates'] = None

    try:
        n_site = PeriodicSite(Element("N"), o_site.frac_coords, s.lattice)
        n_ga = Substitution(s, n_site)
        results['antisite_charge_states'] = n_ga.get_charge_states()
    except Exception:
        results['antisite_charge_states'] = None

    return results
